import AppKit
import CryptoKit
import SwiftData

@MainActor
enum ClipboardHistory {
    enum CaptureResult {
        case captured
        case ignored
        case failed(Error)
    }

    enum Kind: String {
        case text
        case image
        case files
    }

    static let limit = 100
    private static let maximumTextBytes = 2 * 1_024 * 1_024
    private static let maximumImageBytes = 32 * 1_024 * 1_024
    private static let sensitiveTypes: Set<String> = [
        "org.nspasteboard.TransientType",
        "org.nspasteboard.ConcealedType",
        "org.nspasteboard.AutoGeneratedType"
    ]
    private static let sourceType = NSPasteboard.PasteboardType("org.nspasteboard.source")

    static func capture(from pasteboard: NSPasteboard, in context: ModelContext) -> CaptureResult {
        let types = pasteboard.types ?? []
        guard Set(types.map(\.rawValue)).isDisjoint(with: sensitiveTypes),
              !isPasswordManager(pasteboard.string(forType: sourceType)) else { return .ignored }

        guard let item = capturedItem(from: pasteboard) else { return .ignored }
        let fingerprint = fingerprint(kind: item.kind, data: item.fingerprintData)
        var descriptor = FetchDescriptor<ClipboardEntry>(sortBy: [SortDescriptor(\.capturedAt, order: .reverse)])
        descriptor.fetchLimit = limit
        let existing: [ClipboardEntry]
        do {
            existing = try context.fetch(descriptor)
        } catch {
            return .failed(error)
        }

        if let duplicate = existing.first(where: { $0.fingerprint == fingerprint }) {
            duplicate.capturedAt = .now
            do {
                try context.save()
                return .captured
            } catch {
                return .failed(error)
            }
        }

        context.insert(ClipboardEntry(kind: item.kind.rawValue,
                                      fingerprint: fingerprint,
                                      text: item.text,
                                      imageData: item.imageData,
                                      fileURLsJSON: item.fileURLsJSON))
        for oldEntry in existing.dropFirst(limit - 1) { context.delete(oldEntry) }
        do {
            try context.save()
            return .captured
        } catch {
            return .failed(error)
        }
    }

    static func restore(_ entry: ClipboardEntry, to pasteboard: NSPasteboard = .general) -> Bool {
        pasteboard.clearContents()
        switch entry.kind {
        case Kind.text.rawValue:
            return pasteboard.setString(entry.text, forType: .string)
        case Kind.image.rawValue:
            guard let imageData = entry.imageData else { return false }
            return pasteboard.setData(imageData, forType: .png)
        case Kind.files.rawValue:
            let urls = entry.fileURLs
            guard !urls.isEmpty else { return false }
            return pasteboard.writeObjects(urls.map { $0 as NSURL })
        default:
            return false
        }
    }

    private static func capturedItem(from pasteboard: NSPasteboard) -> CapturedItem? {
        if let objects = pasteboard.readObjects(forClasses: [NSURL.self],
                                                options: [.urlReadingFileURLsOnly: true]) as? [NSURL] {
            let urls = objects.map { $0 as URL }
            if !urls.isEmpty, let data = try? JSONEncoder().encode(urls.map(\.path)),
               let json = String(data: data, encoding: .utf8) {
                return CapturedItem(kind: .files, text: "", imageData: nil,
                                    fileURLsJSON: json, fingerprintData: data)
            }
        }

        if let png = pasteboard.data(forType: .png), !png.isEmpty, png.count <= maximumImageBytes {
            return CapturedItem(kind: .image, text: "", imageData: png,
                                fileURLsJSON: "[]", fingerprintData: png)
        }

        if let tiff = pasteboard.data(forType: .tiff), !tiff.isEmpty,
           tiff.count <= maximumImageBytes,
           let image = NSImage(data: tiff),
           let representation = image.tiffRepresentation,
           let bitmap = NSBitmapImageRep(data: representation),
           let png = bitmap.representation(using: .png, properties: [:]),
           png.count <= maximumImageBytes {
            return CapturedItem(kind: .image, text: "", imageData: png,
                                fileURLsJSON: "[]", fingerprintData: png)
        }

        if let text = pasteboard.string(forType: .string), !text.isEmpty,
           let data = text.data(using: .utf8), data.count <= maximumTextBytes {
            return CapturedItem(kind: .text, text: text, imageData: nil,
                                fileURLsJSON: "[]", fingerprintData: data)
        }

        if let urlText = pasteboard.string(forType: .URL), !urlText.isEmpty,
           let data = urlText.data(using: .utf8), data.count <= maximumTextBytes {
            return CapturedItem(kind: .text, text: urlText, imageData: nil,
                                fileURLsJSON: "[]", fingerprintData: data)
        }
        return nil
    }

    private static func isPasswordManager(_ source: String?) -> Bool {
        guard let source = source?.lowercased() else { return false }
        return ["com.agilebits.onepassword", "com.1password.1password"].contains { source.hasPrefix($0) }
    }

    private static func fingerprint(kind: Kind, data: Data) -> String {
        var input = Data(kind.rawValue.utf8)
        input.append(0)
        input.append(data)
        return SHA256.hash(data: input).map { String(format: "%02x", $0) }.joined()
    }

    private struct CapturedItem {
        let kind: Kind
        let text: String
        let imageData: Data?
        let fileURLsJSON: String
        let fingerprintData: Data
    }
}
